with lang as (select id from languages where code = 'en')
insert into toeic_tests (language_id, title, questions, exam_type)
select lang.id, 'TOEFL-like — Test 1', '{"duration_minutes": 45, "part_a": [{"question": "Complète : The professor ___ the lecture with a brief overview.", "options": ["begin", "begins", "began", "beginning"], "correct_index": 2}, {"question": "Complète : Students ___ submit their essays by Friday.", "options": ["must", "musts", "must to", "musted"], "correct_index": 0}, {"question": "Complète : The research paper ___ by three professors before publication.", "options": ["reviewed", "was reviewed", "reviews", "is review"], "correct_index": 1}, {"question": "Complète : If the experiment ___ successful, we will publish the results.", "options": ["is", "was", "were", "будет"], "correct_index": 0}, {"question": "Complète : The library, ___ was built in 1920, has been renovated.", "options": ["that", "which", "who", "where"], "correct_index": 1}, {"question": "Complète : Not only ___ the theory, but he also tested it experimentally.", "options": ["he proposed", "did he propose", "proposed he", "he did propose"], "correct_index": 1}, {"question": "Complète : Having finished her thesis, she ___ to prepare for the defense.", "options": ["begins", "began", "begin", "beginning"], "correct_index": 1}, {"question": "Complète : The findings ___ significant implications for future research.", "options": ["has", "have", "having", "had have"], "correct_index": 1}, {"question": "Complète : It is essential that every student ___ the guidelines.", "options": ["follows", "follow", "followed", "following"], "correct_index": 1}, {"question": "Complète : The data ___ collected over a five-year period.", "options": ["was", "were", "is", "has"], "correct_index": 1}, {"question": "Complète : ___ the limited funding, the project was completed successfully.", "options": ["Although", "Because", "Despite", "So"], "correct_index": 2}, {"question": "Complète : The committee is expected ___ a decision by next week.", "options": ["make", "to make", "making", "made"], "correct_index": 1}, {"question": "Complète : This is the study ___ results changed the field.", "options": ["who", "which", "whose", "where"], "correct_index": 2}, {"question": "Complète : Researchers ___ studying this phenomenon for decades.", "options": ["have been", "has been", "are", "were"], "correct_index": 0}, {"question": "Complète : The hypothesis ___ tested rigorously before acceptance.", "options": ["must", "must be", "must to be", "musting"], "correct_index": 1}, {"question": "Complète : She is known ___ her contributions to linguistics.", "options": ["for", "of", "with", "at"], "correct_index": 0}, {"question": "Complète : The lecture ___, students had time for questions.", "options": ["Having ended", "Once ended", "Ended", "Ending"], "correct_index": 1}, {"question": "Complète : This theory ___ widely accepted in the scientific community.", "options": ["is", "are", "be", "being"], "correct_index": 0}, {"question": "Complète : The professor ___ we submit our drafts early.", "options": ["suggested", "suggested that", "suggests to", "suggesting"], "correct_index": 1}, {"question": "Complète : What the study revealed ___ quite unexpected.", "options": ["was", "were", "have been", "being"], "correct_index": 0}, {"question": "Complète : The seminar ___ postponed due to low enrollment.", "options": ["was", "is being", "has", "were"], "correct_index": 0}, {"question": "Complète : Few students ___ aware of the new requirements.", "options": ["is", "are", "was", "has been"], "correct_index": 1}, {"question": "Complète : The article, published last year, ___ widely cited.", "options": ["has been", "have been", "was being", "is being"], "correct_index": 0}, {"question": "Complète : It was the methodology ___ raised the most questions.", "options": ["that", "who", "which is", "what"], "correct_index": 0}, {"question": "Complète : The results ___, the team began writing the report.", "options": ["analyzed", "having been analyzed", "analyze", "analyzing"], "correct_index": 1}, {"question": "Complète : This approach differs ___ the traditional method.", "options": ["of", "from", "with", "to"], "correct_index": 1}, {"question": "Complète : The professor recommended ___ additional sources.", "options": ["consult", "to consult", "consulting", "consulted"], "correct_index": 2}, {"question": "Complète : Should the results ___ inconclusive, further research will be needed.", "options": ["prove", "proved", "proving", "will prove"], "correct_index": 0}, {"question": "Complète : The university ___ known for its research programs.", "options": ["is well", "well is", "is being well", "was being"], "correct_index": 0}, {"question": "Complète : The paper ___ before the conference deadline.", "options": ["must submit", "must be submitted", "must submitted", "must being submitted"], "correct_index": 1}], "part_b": [{"title": "Extrait de cours (biologie)", "passage": "Photosynthesis is the process by which plants convert light energy into chemical energy. This process occurs primarily in the chloroplasts of plant cells, where chlorophyll absorbs sunlight. The energy captured is then used to convert carbon dioxide and water into glucose, releasing oxygen as a byproduct.", "questions": [{"question": "What is photosynthesis?", "options": ["A process of respiration", "Converting light energy into chemical energy", "A type of cell division", "A form of pollination"], "correct_index": 1}, {"question": "Where does this process mainly occur?", "options": ["In the nucleus", "In chloroplasts", "In the roots", "In the stem"], "correct_index": 1}, {"question": "What absorbs sunlight?", "options": ["Glucose", "Chlorophyll", "Oxygen", "Water"], "correct_index": 1}, {"question": "What is produced as a byproduct?", "options": ["Carbon dioxide", "Oxygen", "Nitrogen", "Water"], "correct_index": 1}, {"question": "What two substances are converted into glucose?", "options": ["Oxygen and nitrogen", "Carbon dioxide and water", "Light and heat", "Water and glucose"], "correct_index": 1}, {"question": "What is the primary energy source for this process?", "options": ["Heat", "Sunlight", "Soil nutrients", "Water pressure"], "correct_index": 1}]}, {"title": "Extrait académique (histoire)", "passage": "The Industrial Revolution, which began in Britain in the late eighteenth century, transformed manufacturing processes and society at large. New machinery increased production efficiency dramatically, but it also led to significant social changes, including urbanization and shifts in labor practices.", "questions": [{"question": "Where did the Industrial Revolution begin?", "options": ["France", "Britain", "Germany", "The United States"], "correct_index": 1}, {"question": "When did it begin?", "options": ["Early seventeenth century", "Late eighteenth century", "Nineteenth century", "Twentieth century"], "correct_index": 1}, {"question": "What did new machinery increase?", "options": ["Population", "Production efficiency", "Agricultural land", "Literacy rates"], "correct_index": 1}, {"question": "What social change is mentioned?", "options": ["Decreased urbanization", "Urbanization", "Population decline", "Reduced trade"], "correct_index": 1}, {"question": "What else changed according to the passage?", "options": ["Climate", "Labor practices", "Currency", "Language"], "correct_index": 1}, {"question": "What is the overall subject of the passage?", "options": ["A biography", "A historical transformation", "A scientific discovery", "A political conflict"], "correct_index": 1}]}, {"title": "Extrait académique (psychologie)", "passage": "Cognitive load theory suggests that learning is impaired when working memory is overwhelmed with information. Instructors can reduce cognitive load by presenting material in smaller chunks and eliminating unnecessary details, which allows students to process new information more effectively.", "questions": [{"question": "What does cognitive load theory suggest?", "options": ["Learning improves with more information", "Learning is impaired when memory is overwhelmed", "Memory has no limits", "Chunking has no effect"], "correct_index": 1}, {"question": "What can instructors do to help?", "options": ["Add more details", "Present material in smaller chunks", "Increase lecture length", "Remove all structure"], "correct_index": 1}, {"question": "What should be eliminated?", "options": ["All examples", "Unnecessary details", "Working memory", "Assessments"], "correct_index": 1}, {"question": "What is affected when memory is overwhelmed?", "options": ["Physical health", "Learning", "Attendance", "Motivation only"], "correct_index": 1}, {"question": "What does ''working memory'' relate to in this context?", "options": ["Long-term storage", "Processing new information", "Physical strength", "Sleep patterns"], "correct_index": 1}, {"question": "What is the main topic of the passage?", "options": ["A teaching strategy based on cognitive theory", "A history lesson", "A biology experiment", "A grammar rule"], "correct_index": 0}]}, {"title": "Extrait académique (économie)", "passage": "Opportunity cost refers to the value of the next best alternative that must be given up when making a decision. This concept is fundamental in economics because it highlights that resources are limited and every choice involves a trade-off.", "questions": [{"question": "What is opportunity cost?", "options": ["The price of a product", "The value of the next best alternative given up", "A type of tax", "A government subsidy"], "correct_index": 1}, {"question": "Why is this concept fundamental in economics?", "options": ["It explains inflation", "It highlights resource limitations and trade-offs", "It predicts stock prices", "It defines currency value"], "correct_index": 1}, {"question": "What does every choice involve, according to the passage?", "options": ["No consequence", "A trade-off", "A guaranteed profit", "A tax increase"], "correct_index": 1}, {"question": "What is limited, according to the passage?", "options": ["Time only", "Resources", "Population", "Information"], "correct_index": 1}, {"question": "What happens when you make a decision?", "options": ["Nothing is given up", "You give up the next best alternative", "You gain unlimited resources", "Prices decrease"], "correct_index": 1}, {"question": "What field is this concept most associated with?", "options": ["Biology", "Economics", "History", "Linguistics"], "correct_index": 1}]}, {"title": "Extrait académique (linguistique)", "passage": "Language acquisition in children follows a remarkably consistent pattern across cultures, suggesting an innate biological capacity for language. Researchers have observed that children progress through similar stages, from babbling to single words, then to simple sentences, regardless of the language being learned.", "questions": [{"question": "What pattern does language acquisition follow?", "options": ["A random pattern", "A consistent pattern across cultures", "No clear pattern", "A pattern only in English speakers"], "correct_index": 1}, {"question": "What does this consistency suggest?", "options": ["Language is entirely learned", "An innate biological capacity for language", "Children copy adults exactly", "Culture determines language ability"], "correct_index": 1}, {"question": "What is the first stage mentioned?", "options": ["Simple sentences", "Babbling", "Complex grammar", "Reading"], "correct_index": 1}, {"question": "What stage comes after single words?", "options": ["Babbling", "Simple sentences", "Silence", "Reading fluency"], "correct_index": 1}, {"question": "Does the pattern depend on the specific language?", "options": ["Yes, entirely", "No, it''s similar regardless of language", "Only for European languages", "Not mentioned"], "correct_index": 1}, {"question": "What is the main claim of the passage?", "options": ["Language learning is purely cultural", "Language acquisition has a biological basis", "Children learn language from books", "All languages are identical"], "correct_index": 1}]}]}'::jsonb, 'toefl'
from lang;

